<template>
  <div class="page-heading"><div><h1 class="page-title">推广数据{{ title }}</h1><p>{{ description }}。每个账户的下一行展示与上一自然周期的同比；无可比基数时显示“—”。</p></div></div>
  <div class="content-panel"><div class="toolbar"><el-select v-model="accountId" clearable placeholder="全部推广账户" style="width:220px"><el-option v-for="a in accounts" :key="a.id" :label="`${a.platform} · ${a.name}`" :value="a.id" /></el-select><el-date-picker v-model="dateRange" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期" /><el-button type="primary" :loading="loading" @click="load">查询</el-button></div><div class="table-wrap" v-loading="loading"><table class="summary-table"><thead><tr><th>{{ title }}</th><th>账户</th><th v-for="column in visibleColumns" :key="column.key">{{ fieldLabel(column.key, column.label) }}</th></tr></thead><tbody><template v-for="row in rows" :key="`${row.periodStart}-${row.account.id}`"><tr><td>{{ row.periodLabel }}</td><td>{{ row.account.platform }} · {{ row.account.name }}</td><td v-for="column in visibleColumns" :key="column.key">{{ display(row, column.key) }}</td></tr><tr class="comparison-row"><td colspan="2">同比</td><td v-for="column in visibleColumns" :key="column.key">{{ comparison(row, column.key) }}</td></tr></template><template v-if="rows.length"><tr class="total-row"><td colspan="2">合计</td><td v-for="column in visibleColumns" :key="column.key">{{ display(total, column.key) }}</td></tr><tr class="total-comparison-row"><td colspan="2">合计同比</td><td v-for="column in visibleColumns" :key="column.key">{{ comparison(total, column.key) }}</td></tr></template><tr v-if="!rows.length"><td :colspan="visibleColumns.length + 2" class="empty">暂无数据</td></tr></tbody></table></div></div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { getPromotionAccounts, getPromotionMetricFields, getPromotionMonthly, getPromotionWeekly, type PromotionAccountItem, type PromotionMetricFieldItem, type PromotionSummaryItem } from '../api/admin';
const props = defineProps<{ mode: 'week' | 'month' }>();
const title = props.mode === 'week' ? '周统计' : '月统计'; const description = props.mode === 'week' ? '按周一至周日的自然周汇总' : '按每月 1 日至月末的自然月汇总';
const dateString = (date: Date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
const currentRange = () => { const start = new Date(); if (props.mode === 'week') { start.setDate(start.getDate() - ((start.getDay() + 6) % 7)); const end = new Date(start); end.setDate(end.getDate() + 6); return [dateString(start), dateString(end)]; } start.setDate(1); const end = new Date(start.getFullYear(), start.getMonth() + 1, 0); return [dateString(start), dateString(end)]; };
const accounts = ref<PromotionAccountItem[]>([]); const fields = ref<PromotionMetricFieldItem[]>([]); const rows = ref<PromotionSummaryItem[]>([]); const loading = ref(false); const accountId = ref(''); const dateRange = ref<string[]>(currentRange());
const columns = [{ key: 'spend', label: '消费', type: 'number' }, { key: 'impressions', label: '展现', type: 'integer' }, { key: 'clicks', label: '点击', type: 'integer' }, { key: 'clickRate', label: '点击率', type: 'rate' }, { key: 'leads', label: '总表单', type: 'integer' }, { key: 'validLeads', label: '有效表单', type: 'integer' }, { key: 'validRate', label: '有效率', type: 'rate' }, { key: 'averageCost', label: '平均成本', type: 'number' }, { key: 'validCost', label: '有效成本', type: 'number' }, { key: 'appointments', label: '到院', type: 'integer' }, { key: 'transactions', label: '成交', type: 'integer' }, { key: 'conversionRate', label: '成交率', type: 'rate' }, { key: 'arrivalRate', label: '到诊率', type: 'rate' }, { key: 'validArrivalRate', label: '有效到诊率', type: 'rate' }, { key: 'arrivalCost', label: '到院成本', type: 'number' }, { key: 'revenue', label: '实收', type: 'number' }, { key: 'roi', label: '投产比', type: 'number' }] as const;
type ColumnKey = typeof columns[number]['key'];
const visibleColumns = computed(() => columns.filter((column) => fields.value.find((field) => field.key === column.key)?.isVisible !== false));
const fieldLabel = (key: string, fallback: string) => fields.value.find((field) => field.key === key)?.label || fallback;
const value = (row: PromotionSummaryItem, key: ColumnKey): number | null => key in row.calculated ? row.calculated[key as keyof typeof row.calculated] : Number(row[key as keyof PromotionSummaryItem]);
const display = (row: PromotionSummaryItem, key: ColumnKey) => { const column = columns.find((item) => item.key === key)!; const result = value(row, key); if (result === null || !Number.isFinite(result)) return '—'; if (column.type === 'rate') return `${(result * 100).toFixed(2)}%`; if (column.type === 'integer') return String(result); return result.toFixed(2); };
const comparison = (row: PromotionSummaryItem, key: ColumnKey) => { if (!row.previous) return '—'; const current = value(row, key); const previous = value(row.previous as PromotionSummaryItem, key); if (current === null || previous === null || !Number.isFinite(current) || !Number.isFinite(previous) || previous === 0) return '—'; const result = (current - previous) / Math.abs(previous) * 100; return `${result > 0 ? '+' : ''}${result.toFixed(2)}%`; };
const aggregate = (source: PromotionSummaryItem[]): PromotionSummaryItem => { const add = (key: keyof PromotionSummaryItem) => source.reduce((sum, row) => sum + Number(row[key] || 0), 0); const base: any = { periodLabel: '合计', periodStart: '', periodEnd: '', account: { id: 'total', name: '合计', platform: '' }, days: add('days'), spend: add('spend'), impressions: add('impressions'), clicks: add('clicks'), leads: add('leads'), validLeads: add('validLeads'), appointments: add('appointments'), transactions: add('transactions'), revenue: add('revenue') }; const calculated = (row: any) => ({ clickRate: row.impressions ? row.clicks / row.impressions : null, validRate: row.leads ? row.validLeads / row.leads : null, averageCost: row.leads ? row.spend / row.leads : null, validCost: row.validLeads ? row.spend / row.validLeads : null, conversionRate: row.appointments ? row.transactions / row.appointments : null, arrivalRate: row.leads ? row.appointments / row.leads : null, validArrivalRate: row.validLeads ? row.appointments / row.validLeads : null, arrivalCost: row.appointments ? row.spend / row.appointments : null, roi: row.spend ? row.revenue / row.spend : null }); const previous = source.filter((row) => row.previous).map((row) => row.previous as PromotionSummaryItem); const previousBase = previous.length ? aggregate(previous) : null; return { ...base, calculated: calculated(base), previous: previousBase } as PromotionSummaryItem; };
const total = computed(() => aggregate(rows.value));
async function load() { loading.value = true; try { const params = { accountId: accountId.value, dateFrom: dateRange.value?.[0] || '', dateTo: dateRange.value?.[1] || '' }; rows.value = props.mode === 'week' ? await getPromotionWeekly(params) : await getPromotionMonthly(params); } finally { loading.value = false; } }
onMounted(async () => { [accounts.value, fields.value] = await Promise.all([getPromotionAccounts(), getPromotionMetricFields()]); await load(); });
</script>

<style scoped>.page-heading { margin-bottom:20px; }.page-title { margin:0 0 6px; }.page-heading p { margin:0; color:var(--admin-text-muted); }.toolbar { display:flex; gap:12px; flex-wrap:wrap; margin-bottom:18px; }.table-wrap { overflow:auto; }.summary-table { width:100%; min-width:1740px; table-layout:fixed; border-collapse:collapse; font-size:13px; text-align:center; }.summary-table th,.summary-table td { padding:7px 8px; border:1px solid var(--admin-border); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }.summary-table th:first-child,.summary-table td:first-child { width:96px; }.summary-table th:nth-child(2),.summary-table td:nth-child(2) { width:168px; max-width:168px; }.summary-table th:nth-child(n + 3),.summary-table td:nth-child(n + 3) { width:100px; }.summary-table th { background:#f5f7fa; color:var(--admin-text); font-weight:650; }.summary-table tbody tr:hover td { background:#f7fbff; }.summary-table .comparison-row td { color:#315b37; background:#eaf5ea; }.summary-table .comparison-row td:first-child { font-weight:650; }.summary-table .total-row td { background:#ffe699; font-weight:700; }.summary-table .total-comparison-row td { color:#254a68; background:#d9e8f3; font-weight:650; }.empty { padding:32px !important; color:var(--admin-text-muted); }</style>
